{"cards": [{"node_code": "N_153c4a7d436fcb20", "definition": "研究城市范围内货物集散、中转、配送网络构建及末端交付的领域，涵盖城市物流体系规划、配送路径优化、仓储布局及智慧物流技术应用。", "boundary": "本节点聚焦于城市空间内的“货”流组织。若内容侧重城市客运或人员出行归入市内交通运输；若侧重宏观区域物流枢纽布局归入综合运输体制与结构；若侧重纯物流算法理论归入系统工程。本节点包含城市配送网络、末端配送（如快递、即时配送）及智慧物流系统。", "includes": ["城市配送网络规划、路径优化及仓储设施布局", "城市末端配送模式、即时配送及快递物流运营", "城市智慧物流系统、自动化配送技术及绿色物流实践"], "excludes": ["城市客运交通组织（归入市内交通运输）", "宏观区域物流枢纽与多式联运体系（归入综合运输体制与结构）", "纯物流数学建模或算法理论研究（归入交通运输系统工程）"], "sibling_distinctions": [{"other_code": "N_30c642ea839647f5", "rule": "本节点侧重城市内的货物运输与配送；兄弟节点侧重城市内的人员出行与客运交通组织。"}, {"other_code": "N_12f37b4d1e611b05", "rule": "本节点侧重货物物流；兄弟节点侧重共享汽车、共享单车等出行服务。若涉及共享货运车辆，需视主要业务属性，通常归入本节点或市内运输。"}], "cross_boundary_rule": "涉及城市物流的经济分析归入城市交通运输经济；涉及城市物流的纯算法优化归入系统工程；涉及城市物流的环保措施可关联绿色城市交通，但主挂载仍为本节点。"}, {"node_code": "N_c56b5360178a418b", "definition": "研究城市交通系统中节能减排、低碳出行、交通环境改善及绿色交通规划与治理的领域，涵盖绿色交通政策、新能源交通及交通环境影响评估。", "boundary": "本节点聚焦于城市交通的“绿色”与“可持续”属性。若内容侧重具体新能源车辆技术归入对应车辆工程节点；若侧重宏观交通规划归入城市移动性规划；若侧重交通污染控制工程归入环境工程。本节点包含绿色交通规划、居住与交通环境协调及低碳交通政策。", "includes": ["城市绿色交通规划、低碳交通体系构建及政策制定", "交通环境影响评估、噪声与空气污染控制策略", "新能源交通应用、慢行交通系统优化及绿色出行引导"], "excludes": ["纯新能源车辆制造技术（归入车辆工程或相关工业节点）", "宏观区域交通规划（归入综合运输体制与结构）", "纯环境工程污染治理技术（归入环境科学与工程）"], "sibling_distinctions": [{"other_code": "N_7bc16b66bc23538a", "rule": "本节点侧重交通的环保与可持续属性；兄弟节点侧重交通系统的整体规划、出行需求管理及效率优化。绿色规划是移动性规划的一个维度，但本节点更强调环境效益。"}, {"other_code": "N_153c4a7d436fcb20", "rule": "本节点侧重交通系统的整体绿色化；兄弟节点侧重物流环节。若涉及绿色物流，主挂载视内容侧重，若为物流运营中的环保措施归入城市物流与配送，若为宏观绿色交通政策归入本节点。"}], "cross_boundary_rule": "涉及绿色交通的经济成本效益分析归入城市交通运输经济；涉及绿色交通的具体技术实现（如电池技术）归入相关工程节点；涉及绿色交通的规划方法归入城市移动性规划。"}]}
